namespace NativeBinaryTools;

internal static class MimallocSymbolHeaderRenderer
{
    public static string Render(IReadOnlySet<string> identifiers, IReadOnlySet<string> includes)
    {
        ArgumentNullException.ThrowIfNull(identifiers);
        ArgumentNullException.ThrowIfNull(includes);

        var lines = new List<string>
        {
            "// Generated by NativeBinaryTools mimalloc-symbols. Do not edit.",
            "#pragma once",
            string.Empty,
        };
        foreach (var identifier in identifiers.Order(StringComparer.Ordinal))
        {
            lines.Add($"#define {identifier} {MimallocSymbolParser.Prefixed(identifier)}");
        }

        var mimallocIncludes = includes
            .Where(MimallocSymbolParser.IsMimallocLinkerInclude)
            .Order(StringComparer.Ordinal)
            .ToArray();
        if (mimallocIncludes.Length > 0)
        {
            lines.Add(string.Empty);
            lines.Add("#if defined(_MSC_VER)");
            foreach (var symbol in mimallocIncludes)
            {
                lines.Add($"#pragma comment(linker, \"/include:{MimallocSymbolParser.Prefixed(symbol)}\")");
            }

            lines.Add("#endif");
        }

        lines.Add(string.Empty);
        return string.Join("\n", lines);
    }
}
